const defaults=()=>({clients:[],projects:[],documents:[]});
function loadLocal(){try{return JSON.parse(localStorage.getItem(localKey))||defaults()}catch{return defaults()}}
function saveLocal(){try{localStorage.setItem(localKey,JSON.stringify({clients,projects,documents:docs}));return true}catch(e){console.error("Local save failed",e);throw new Error("Local saving failed: browser storage may be full or disabled. Please check browser settings and try again.")}}
function esc(s=""){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function today(){return new Date().toISOString().slice(0,10)}
function nextNo(type){const p={quotation:"QTN",agreement:"AGR",invoice:"INV"}[type];const y=new Date().getFullYear();const used=new Set(docs.filter(d=>d.type===type&&String(d.number).startsWith(`${p}-${y}-`)).map(d=>String(d.number)));let seq=1;while(used.has(`${p}-${y}-${String(seq).padStart(4,"0")}`))seq++;return `${p}-${y}-${String(seq).padStart(4,"0")}`}
function hydrate(){
 const d=loadLocal();
 clients=(d.clients||[]).map(x=>({...x,id:x.id||crypto.randomUUID()}));
 const clientIds=new Set(clients.map(x=>x.id));
 projects=(d.projects||[]).map(x=>({...x,id:x.id||crypto.randomUUID(),client_id:x.client_id&&clientIds.has(x.client_id)?x.client_id:null}));
 const projectIds=new Set(projects.map(x=>x.id));
 docs=(d.documents||[]).map(x=>({...x,id:x.id||crypto.randomUUID(),client_id:x.client_id&&clientIds.has(x.client_id)?x.client_id:null,project_id:x.project_id&&projectIds.has(x.project_id)?x.project_id:null}));
 saveLocal();
}
async function syncLocalToSupabase(){
 const local=loadLocal();
 if(!supabaseClient||!currentUserId)return;
 const now=new Date().toISOString();
 const clientsToSync=(local.clients||[]).map(x=>({...x,owner_id:currentUserId,updated_at:now}));
 const projectsToSync=(local.projects||[]).map(x=>({...x,owner_id:currentUserId,updated_at:now}));
 const docsToSync=(local.documents||[]).map(x=>({...x,owner_id:currentUserId,updated_at:now}));
 if(clientsToSync.length){const {error}=await supabaseClient.from("clients").upsert(clientsToSync,{onConflict:"id"});if(error)throw error}
 if(projectsToSync.length){const {error}=await supabaseClient.from("projects").upsert(projectsToSync,{onConflict:"id"});if(error)throw error}
 if(docsToSync.length){const {error}=await supabaseClient.from("documents").upsert(docsToSync,{onConflict:"id"});if(error)throw error}
}
async function persist(kind,row){
 const base={...row,id:row.id||crypto.randomUUID(),created_at:row.created_at||new Date().toISOString(),updated_at:new Date().toISOString()};
 if(!online)return base;
 const table=kind==="client"?"clients":kind==="project"?"projects":"documents";
 const payload={...base,owner_id:currentUserId};
 try{
   const {data,error}=await supabaseClient.from(table).upsert(payload,{onConflict:"id"}).select().single();
   if(error)throw error;
   return data;
 }catch(e){
   console.error("Online save failed",e);
   throw new Error("Online save failed: "+(e?.message||"Check your connection and Supabase permissions."));
 }
}
async function removeRecord(kind,id){
 const table=kind==="client"?"clients":kind==="project"?"projects":"documents";
 try{
   if(online){
     const {error}=await supabaseClient.from(table).delete().eq("id",id);
     if(error)throw error;
   }
   if(kind==="client")clients=clients.filter(x=>x.id!==id);
   if(kind==="project")projects=projects.filter(x=>x.id!==id);
   if(kind==="document")docs=docs.filter(x=>x.id!==id);
   saveLocal();render();
 }catch(e){
   alert("Delete failed: "+(e?.message||"Please check your Supabase connection and permissions."));
 }
}
function showAuth(message=""){
 const gate=$("#auth-gate"),app=$("#admin-app"),err=$("#login-error");
 if(gate)gate.style.display="grid";if(app)app.style.display="none";if(err)err.textContent=message;
 online=false;currentUserId=null;
}
async function connect(){
 const url=localStorage.getItem("pb_sb_url")||DEFAULT_SUPABASE_URL,key=localStorage.getItem("pb_sb_key")||DEFAULT_SUPABASE_KEY;
 if(!url||!key){showAuth("Supabase connection is not configured. Contact the site administrator.");updateConnection();return false}
 try{
   const {createClient}=supabase;supabaseClient=supabaseClient||createClient(url,key);
   const {data:sessionData,error:sessionError}=await supabaseClient.auth.getSession();
   if(sessionError)throw sessionError;
   if(!sessionData.session){showAuth();updateConnection();return false}
   const user=sessionData.session.user;
   const {data:adminRecord,error:adminError}=await supabaseClient.from("business_admins").select("user_id").eq("user_id",user.id).maybeSingle();
   if(adminError)throw new Error("Admin access could not be verified. Apply the admin access SQL in Supabase first.");
   if(!adminRecord){await supabaseClient.auth.signOut();showAuth("This account is not authorised for the company admin area.");updateConnection();return false}
   currentUserId=user.id;
   await syncLocalToSupabase();
   const [c,p,d]=await Promise.all([
     supabaseClient.from("clients").select("*").order("created_at",{ascending:false}),
     supabaseClient.from("projects").select("*").order("created_at",{ascending:false}),
     supabaseClient.from("documents").select("*").order("created_at",{ascending:false})
   ]);
   if(c.error||p.error||d.error)throw c.error||p.error||d.error;
   clients=c.data||[];projects=p.data||[];docs=d.data||[];online=true;saveLocal();
   $("#auth-gate").style.display="none";$("#admin-app").style.display="flex";
   updateConnection();render();return true;
 }catch(e){console.error(e);showAuth(e?.message||"Unable to connect. Check the Supabase configuration.");updateConnection();return false}
}
function updateConnection(){$("#connection-label").textContent=online?"Supabase connected":"Local saved mode";$(".status-dot").style.background=online?"#54c779":"#e5b744"}
function navTo(v){view=v;document.querySelectorAll(".nav").forEach(b=>b.classList.toggle("active",b.dataset.view===v));render()}
function title(){return ({dashboard:"Dashboard",clients:"Clients",projects:"Projects",documents:"Documents",payments:"Payments",quotations:"Quotations",agreements:"Agreements",invoices:"VAT Invoices",settings:"Settings & Connection",taxreports:"Monthly / Yearly Tax Reports"})[view]}
function render(){ $("#page-title").textContent=title(); const v=$("#view"); if(view==="dashboard")v.innerHTML=dashboard();else if(view==="clients")v.innerHTML=clientPage();else if(view==="projects")v.innerHTML=projectPage();else if(view==="documents")v.innerHTML=allDocumentsPage();else if(view==="payments")v.innerHTML=paymentsPage();else if(["quotations","agreements","invoices"].includes(view))v.innerHTML=documentsPage(view);else if(view==="taxreports")v.innerHTML=taxReportsPage();else v.innerHTML=settingsPage();bindView()}
function taxReportsPage(){const now=new Date(),defaultYear=String(now.getFullYear()),defaultMonth=String(now.getMonth()+1).padStart(2,"0");const years=[...new Set([defaultYear,...docs.filter(d=>d.type==="invoice"&&d.doc_date).map(d=>String(d.doc_date).slice(0,4))])].sort().reverse();return `<div class="notice">Tax report is based on saved VAT invoices and recorded payments. Check the figures with your accountant before filing a tax return.</div><div class="card"><div class="form-grid"><div class="field"><label>Report period</label><select id="tax-period"><option value="month">Monthly</option><option value="year">Yearly</option></select></div><div class="field"><label>Year</label><select id="tax-year">${years.map(y=>`<option value="${esc(y)}" ${y===defaultYear?"selected":""}>${esc(y)}</option>`).join("")}</select></div><div class="field" id="tax-month-wrap"><label>Month</label><select id="tax-month">${Array.from({length:12},(_,i)=>{const m=String(i+1).padStart(2,"0");return `<option value="${m}" ${m===defaultMonth?"selected":""}>${new Date(Number(defaultYear),i,1).toLocaleString("en-GB",{month:"long"})}</option>`}).join("")}</select></div></div><div class="toolbar" style="margin-top:12px"><button class="btn primary" id="tax-export">Download CSV report</button></div></div><div id="tax-report-results"></div>`}
function taxReportRows(){const period=$("#tax-period")?.value||"month",year=$("#tax-year")?.value||String(new Date().getFullYear()),month=$("#tax-month")?.value||String(new Date().getMonth()+1).padStart(2,"0");const list=docs.filter(d=>d.type==="invoice"&&d.doc_date&&String(d.doc_date).slice(0,4)===year&&(period==="year"||String(d.doc_date).slice(5,7)===month));const byClient=new Map();for(const d of list){const name=clients.find(c=>String(c.id)===String(d.client_id))?.name||d.client_name||"Unassigned";const r=byClient.get(name)||{name,invoices:0,net:0,vat:0,gross:0,paid:0,outstanding:0};r.invoices++;r.net+=Number(d.subtotal||0);r.vat+=Number(d.vat||0);r.gross+=Number(d.total||0);r.paid+=Math.min(Math.max(0,Number(d.paid_amount||0)),Math.max(0,Number(d.total||0)));r.outstanding+=Math.max(0,Number(d.total||0)-Math.max(0,Number(d.paid_amount||0)));byClient.set(name,r)}return{period,year,month,list,rows:[...byClient.values()].sort((a,b)=>a.name.localeCompare(b.name))}}
function renderTaxReport(){const host=$("#tax-report-results");if(!host)return;const r=taxReportRows(),sum=k=>r.rows.reduce((a,x)=>a+x[k],0),periodLabel=r.period==="year"?r.year:new Date(Number(r.year),Number(r.month)-1,1).toLocaleString("en-GB",{month:"long",year:"numeric"});host.innerHTML=`<div class="section-head"><h2>${esc(periodLabel)} — Tax summary</h2></div><div class="grid"><div class="card"><div class="metric-label">Invoices</div><div class="metric">${r.list.length}</div></div><div class="card"><div class="metric-label">Net sales</div><div class="metric">${money(sum("net"))}</div></div><div class="card"><div class="metric-label">VAT charged</div><div class="metric">${money(sum("vat"))}</div></div><div class="card"><div class="metric-label">Gross invoiced</div><div class="metric">${money(sum("gross"))}</div></div></div><div class="section-head"><h2>Client-wise breakdown</h2></div>${r.rows.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>Invoices</th><th>Net (£)</th><th>VAT (£)</th><th>Gross (£)</th><th>Paid (£)</th><th>Outstanding (£)</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.invoices}</td><td>${money(x.net)}</td><td>${money(x.vat)}</td><td>${money(x.gross)}</td><td>${money(x.paid)}</td><td>${money(x.outstanding)}</td></tr>`).join("")}</tbody></table></div>`:`<div class="card empty">No invoices found for this period.</div>`}`}
function exportTaxReport(){const r=taxReportRows(),rows=[["Period",r.period==="year"?r.year:`${r.year}-${r.month}`],["Client","Invoice count","Net GBP","VAT GBP","Gross GBP","Paid GBP","Outstanding GBP"],...r.rows.map(x=>[x.name,x.invoices,x.net.toFixed(2),x.vat.toFixed(2),x.gross.toFixed(2),x.paid.toFixed(2),x.outstanding.toFixed(2)])];const csv=rows.map(row=>row.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(",")).join("\r\n");const blob=new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`tax-report-${r.period==="year"?r.year:`${r.year}-${r.month}`}.csv`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
function dashboard(){return `<div class="grid">
<div class="card"><div class="metric-label">Total clients</div><div class="metric">${clients.length}</div><div class="metric-note">Saved client records</div></div>
<div class="card"><div class="metric-label">Projects</div><div class="metric">${projects.length}</div><div class="metric-note">Tracked projects</div></div>
<div class="card"><div class="metric-label">Documents</div><div class="metric">${docs.length}</div><div class="metric-note">Quotes, agreements and invoices</div><button class="btn" data-view="documents">View documents</button></div>
<div class="card"><div class="metric-label">Outstanding invoices</div><div class="metric">${money(docs.filter(d=>d.type==="invoice").reduce((a,d)=>a+Math.max(0,Number(d.total||0)-Number(d.paid_amount||0)),0))}</div><div class="metric-note">Unpaid invoice totals</div><button class="btn" data-view="payments">View payments</button></div></div>
<div class="section-head"><h2>Quick actions</h2></div><div class="card toolbar"><button class="btn primary" data-action="add-client">+ Add client</button><button class="btn" data-action="new-quotation">+ Create quotation</button><button class="btn" data-action="new-agreement">+ Create agreement</button><button class="btn" data-action="new-invoice">+ Create VAT invoice</button></div>
<div class="section-head"><h2>Recent documents</h2><button class="btn" data-view="quotations">View documents</button></div>${docTable(docs.slice(0,6))}`}
function clientPage(){return `<div class="section-head"><h2>Client records</h2><div class="toolbar"><input class="search" id="client-search" placeholder="Search name, email, phone or address"><button class="btn primary" data-action="add-client">+ Add client</button></div></div><div id="client-table">${clientTable(clients)}</div>`}
function clientTable(list){if(!list.length)return `<div class="card empty">No clients saved yet. Select “Add client” to create your first record.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Client</th><th>Contact</th><th>Address</th><th>Projects</th><th>Actions</th></tr></thead><tbody>${list.map(c=>`<tr><td><b>${esc(c.name)}</b><small>${esc(c.client_no||"")}</small></td><td>${esc(c.email||"—")}<small>${esc(c.phone||"")}</small></td><td>${esc(c.address||"—")}</td><td>${projects.filter(p=>p.client_id===c.id).length}</td><td><div class="actions"><button class="btn" data-edit-client="${c.id}">Edit</button><button class="btn danger" data-delete-client="${c.id}">Delete</button></div></td></tr>`).join("")}</tbody></table></div>`}
function projectPage(){return `<div class="section-head"><h2>Project register</h2><button class="btn primary" data-action="add-project">+ Add project</button></div>${projects.length?`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Client</th><th>Address</th><th>Status</th><th>Actions</th></tr></thead><tbody>${projects.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.project_no||"")}</small></td><td>${esc(clients.find(c=>c.id===p.client_id)?.name||"Unknown")}</td><td>${esc(p.address||"—")}</td><td><span class="pill">${esc(p.status||"Active")}</span></td><td><div class="actions"><button class="btn" data-edit-project="${p.id}">Edit</button><button class="btn danger" data-delete-project="${p.id}">Delete</button></div></td></tr>`).join("")}</tbody></table></div>`:`<div class="card empty">No projects added yet.</div>`}`}
function docTypeLabel(t){return ({quotation:"Quotation",agreement:"Agreement",invoice:"VAT Invoice"})[t]||t}
function docTable(list){if(!list.length)return `<div class="card empty">No documents saved yet.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Document</th><th>Client / Project</th><th>Date</th><th>Total incl. VAT</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(d=>`<tr><td><b>${esc(d.number)}</b><small>${docTypeLabel(d.type)}</small></td><td>${esc(clients.find(c=>c.id===d.client_id)?.name||d.client_name||"—")}<small>${esc(d.project_name||"")}</small></td><td>${esc(d.doc_date||"—")}</td><td>${money(d.total)}</td><td><span class="pill ${d.status==="Paid"?"green":""}">${esc(d.status||"Draft")}</span></td><td><div class="actions"><button class="btn" data-preview="${d.id}">Open / Print</button><button class="btn" data-edit-doc="${d.id}">Edit</button>${d.type==="invoice"?`<button class="btn" data-payment="${d.id}">Record payment</button>`:""}<button class="btn danger" data-delete-doc="${d.id}">Delete</button></div></td></tr>`).join("")}</tbody></table></div>`}
function documentsPage(v){const type={quotations:"quotation",agreements:"agreement",invoices:"invoice"}[v];const list=docs.filter(d=>d.type===type).sort((a,b)=>(b.created_at||"").localeCompare(a.created_at||""));return `<div class="section-head"><h2>${docTypeLabel(type)} register</h2><div class="toolbar"><input class="search" id="doc-search" placeholder="Search document number or client"><button class="btn primary" data-action="new-${type}">+ New ${docTypeLabel(type)}</button></div></div><div id="doc-table">${docTable(list)}</div>`}
function allDocumentsPage(){const list=[...docs].sort((a,b)=>(b.created_at||b.doc_date||"").localeCompare(a.created_at||a.doc_date||""));return `<div class="section-head"><h2>All documents</h2><div class="toolbar"><input class="search" id="doc-search" placeholder="Search document number or client"></div></div><div id="doc-table">${docTable(list)}</div>`}
function paymentsPage(){const list=docs.filter(d=>d.type==="invoice").sort((a,b)=>(b.doc_date||"").localeCompare(a.doc_date||""));const total=list.reduce((a,d)=>a+Number(d.total||0),0),paid=list.reduce((a,d)=>a+Math.min(Math.max(0,Number(d.paid_amount||0)),Math.max(0,Number(d.total||0))),0),due=Math.max(0,total-paid);return `<div class="grid"><div class="card"><div class="metric-label">Total invoiced</div><div class="metric">${money(total)}</div></div><div class="card"><div class="metric-label">Payments received</div><div class="metric">${money(paid)}</div></div><div class="card"><div class="metric-label">Outstanding balance</div><div class="metric">${money(due)}</div></div></div><div class="section-head"><h2>Invoice payments</h2></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Client</th><th>Invoice total</th><th>Received</th><th>Balance due</th><th>Status</th><th>Action</th></tr></thead><tbody>${list.map(d=>{const received=Math.min(Math.max(0,Number(d.paid_amount||0)),Math.max(0,Number(d.total||0)));const balance=Math.max(0,Number(d.total||0)-received);return `<tr><td><b>${esc(d.number)}</b><small>${esc(d.doc_date||"")}</small></td><td>${esc(clients.find(c=>c.id===d.client_id)?.name||d.client_name||"—")}</td><td>${money(d.total)}</td><td>${money(received)}</td><td>${money(balance)}</td><td><span class="pill ${balance===0&&Number(d.total||0)>0?"green":""}">${esc(d.status||"Unpaid")}</span></td><td><div class="actions"><button class="btn" data-preview="${d.id}">Open / Print</button><button class="btn" data-payment="${d.id}">Record payment</button></div></td></tr>`}).join("")}</tbody></table></div>`:`<div class="card empty">No invoices available for payment tracking.</div>`}`}
function settingsPage(){return `<div class="notice">Connect your Supabase project to save and sync client, project and document records online. Use the Supabase Project URL and anon/public key only. Never put a service_role key in this browser app.</div><div class="card"><h2 style="margin-top:0;font-size:15px">Supabase connection</h2><div class="form-grid"><div class="field full"><label>Project URL</label><input id="sb-url" placeholder="https://your-project.supabase.co" value="${esc(localStorage.getItem("pb_sb_url")||DEFAULT_SUPABASE_URL)}"></div><div class="field full"><label>Anon / publishable key</label><input id="sb-key" type="password" placeholder="Paste your Supabase anon/public key" value="${esc(localStorage.getItem("pb_sb_key")||DEFAULT_SUPABASE_KEY)}"></div></div><div class="toolbar" style="margin-top:14px"><button class="btn primary" id="connect-btn">Save & connect</button><button class="btn" id="disconnect-btn">Disconnect</button></div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><h2 style="font-size:14px">Account sign-in</h2><p class="hint">Sign in is restricted to authorised company administrators. Admin accounts must be created in Supabase by the project owner.</p><div class="form-grid"><div class="field"><label>Email</label><input id="auth-email" type="email" placeholder="you@example.com"></div><div class="field"><label>Password</label><input id="auth-password" type="password" placeholder="Password"></div></div><div class="toolbar" style="margin-top:12px"><button class="btn primary" id="sign-in">Sign in</button><button class="btn" id="sign-out">Sign out</button></div><p class="hint">Before connecting, run the SQL file in the included supabase folder. Enable email authentication and review the row-level security policies before using real customer information.</p></div><div class="section-head"><h2>Client invoice portal</h2></div><div class="card"><p>Clients can check an invoice online using their invoice number and the email address registered on that invoice. The portal only returns invoice totals, payments and balance due.</p><p><a href="invoice-portal.html" target="_blank" rel="noopener">Open client invoice portal</a></p><p class="hint">For the portal to work for clients on other devices, set the Supabase public project URL and anon key in invoice-portal.js before publishing.</p></div><div class="section-head"><h2>Company details</h2></div><div class="card"><b>${COMPANY}</b><p class="hint">VAT Registered No: ${VAT}</p><p class="hint">Currency: GBP (£) · Standard VAT setting: 20%</p></div>`}
