$("#close-modal").onclick=closeModal;$("#cancel-modal").onclick=closeModal;
$("#client-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const row={...(c.id?{id:c.id}:{}),name:f.get("name").trim(),phone:f.get("phone"),email:f.get("email"),address:f.get("address"),client_no:f.get("client_no")||`CL-${String(Date.now()).slice(-6)}`};if(!row.name)return alert("Client name is required");try{const saved=await persist("client",row);if(c.id)clients=clients.map(x=>x.id===c.id?saved:x);else clients.unshift(saved);saveLocal();closeModal();render()}catch(err){alert(err.message)}};
