function addProjectForm(p=null){
 const editing=!!p;
 modal(`<div class="modal-head"><h2>${editing?"Edit":"Add"} project</h2><button class="btn" id="close-modal">✕</button></div><form id="project-form"><div class="form-grid"><div class="field"><label>Client *</label><select name="client_id" required>${clients.map(c=>`<option value="${c.id}" ${p?.client_id===c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select></div>${field("Project name *","name","e.g. Rear extension","text",p?.name||"")}${field("Project reference","project_no","Auto if blank","text",p?.project_no||"")}<div class="field"><label>Status</label><select name="status">${["Active","On hold","Completed","Cancelled"].map(x=>`<option ${x===(p?.status||"Active")?"selected":""}>${x}</option>`).join("")}</select></div><div class="field full"><label>Project address</label><textarea name="address">${esc(p?.address||"")}</textarea></div></div><div class="modal-foot"><button type="button" class="btn" id="cancel-modal">Cancel</button><button class="btn primary">${editing?"Update":"Save"} project</button></div></form>`);
 $("#close-modal").onclick=closeModal;$("#cancel-modal").onclick=closeModal;
 $("#project-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const row={...(editing?{id:p.id}:{}),client_id:f.get("client_id"),name:f.get("name").trim(),project_no:f.get("project_no")||`PR-${String(Date.now()).slice(-6)}`,status:f.get("status"),address:f.get("address")};if(!row.name)return alert("Project name is required");try{const saved=await persist("project",row);if(editing)projects=projects.map(x=>x.id===p.id?saved:x);else projects.unshift(saved);saveLocal();closeModal();render()}catch(err){alert(err.message)}};
}

const QUOTATION_TERMS = [
 "This quotation is based on the scope and project information stated above. Work not expressly included is excluded unless separately agreed in writing.",
 "Requested additions, specification changes or genuinely unforeseen work will be discussed with the Client and agreed in writing before the additional work proceeds.",
 "The Client shall provide reasonable access, accurate information and any approvals required for the works.",
 "This quotation is valid until the date stated above. Pricing may be reviewed if the scope changes or the quotation expires before acceptance.",
 "All work will follow applicable UK building requirements and standard building practices relevant to the work."
];
